122	export async function deleteR2Object(
123		complianceConfig: ComplianceConfig,
124		accountId: string,
125		bucketName: string,
126		objectName: string,
127		jurisdiction?: string
128	): Promise<void> {
129		const headers: HeadersInit = {};
130		if (jurisdiction !== undefined) {
131			headers["cf-r2-jurisdiction"] = jurisdiction;
132		}
133		await fetchR2Objects(
134			complianceConfig,
135			`/accounts/${accountId}/r2/buckets/${bucketName}/objects/${objectName}`,
136			{ method: "DELETE", headers }
137		);
138	}
