193	/**
194	 * Extract the bucket and key from an object path, validating the bucket name in the process.
195	 *
196	 * Throws when an invalid format is provided or when the bucket name is invalid.
197	 *
198	 * @param objectPath The path passed to wrangler commands in the format `{bucket}/{key}`
199	 * @returns The bucket and key extracted from the object path
200	 */
201	export function validateAndReturnBucketAndKey(objectPath: string): {
202		bucket: string;
203		key: string;
204	} {
205		// Path format is `<bucket>/<key>`
206		const match = /^(?<bucket>[^/]+)\/(?<key>.*)/.exec(objectPath);
207		if (match === null || !match.groups) {
208			throw new UserError(
209				`The object path must be in the form of {bucket}/{key} you provided ${objectPath}`
210			);
211		}
212		const { bucket, key } = match.groups;
213		if (!isValidR2BucketName(bucket)) {
214			throw new UserError(
215				`The bucket name "${bucket}" is invalid. ${bucketFormatMessage}`
216			);
217		}
218	
219		return { bucket, key };
220	}
