19	async function logRequest(request: Request, init?: RequestInit) {
20		logger.debug(`-- START CF API REQUEST: ${request.method} ${request.url}`);
21		const logRequestHeaders = cloneHeaders(request.headers);
22		logRequestHeaders.delete("Authorization");
23		logger.debugWithSanitization(
24			"HEADERS:",
25			JSON.stringify(logRequestHeaders, null, 2)
26		);
27	
28		logger.debugWithSanitization("INIT:", JSON.stringify({ ...init }, null, 2));
29		if (request.body instanceof FormData) {
30			logger.debugWithSanitization(
31				"BODY:",
32				await new Response(request.body).text(),
33				null,
34				2
35			);
36		}
37		logger.debug("-- END CF API REQUEST");
38	}
39	
40	async function logResponse(response: Response) {
41		const jsonText = await response.clone().text();
42		logger.debug(
43			"-- START CF API RESPONSE:",
44			response.statusText,
45			response.status
46		);
47		const logResponseHeaders = cloneHeaders(response.headers);
48		logResponseHeaders.delete("Authorization");
49		logger.debugWithSanitization(
50			"HEADERS:",
51			JSON.stringify(logResponseHeaders, null, 2)
52		);
53		logger.debugWithSanitization("RESPONSE:", jsonText);
54		logger.debug("-- END CF API RESPONSE");
55	}
