57	 * This function constructs an instance of the `Cloudflare` SDK client,
58	 * with a custom fetcher that uses `fetchInternal`.
59	 */
60	export function createCloudflareClient(complianceConfig: ComplianceConfig) {
61		return new Cloudflare({
62			fetch: async (url: RequestInfo, init?: RequestInit): Promise<Response> => {
63				const request = new Request(url, { ...init, duplex: "half" });
64				await requireLoggedIn(complianceConfig);
65				const apiToken = requireApiToken();
66	
67				addAuthorizationHeader(
68					request.headers,
69					apiToken,
70					/* The CF SDK will inject `Bearer dummy` */ true
71				);
72				addUserAgent(request.headers);
73	
74				await logRequest(request, init);
75	
76				const response = await fetch(request.url, request);
77				await logResponse(response);
78				return response;
79			},
80			baseURL: getCloudflareApiBaseUrl(complianceConfig),
81		});
82	}
