[metadata] {"type": "create", "filePath": "/workspace/repo/packages/wrangler/src/r2/helpers/data-catalog.ts", "content": "import { APIError } from "@cloudflare/workers-utils";
import { confirm } from "../../dialogs";
import { logger } from "../../logger";
import { DATA_CATALOG_CONFLICT_ERROR_CODE } from "../constants";

/**
 * The prompt shown when a single write operation (object put/delete, lifecycle
 * add/set) is blocked because the bucket has data catalog enabled.
 */
export const DATA_CATALOG_CONFLICT_PROMPT =
	"Data catalog is enabled for this bucket. Proceeding may leave the data catalog in an invalid state. Continue?";

/**
 * Returns whether an error represents a data catalog conflict returned by the
 * R2 API (an HTTP 409 with error code {@link DATA_CATALOG_CONFLICT_ERROR_CODE}).
 */
export function isDataCatalogConflict(error: unknown): boolean {
	return (
		error instanceof APIError &&
		error.code === DATA_CATALOG_CONFLICT_ERROR_CODE
	);
}

/**
 * Runs an R2 write `operation`, sending the data catalog check header unless
 * `force` was passed. If the API reports a data catalog conflict, the user is
 * prompted; on confirmation the operation is retried without the check header,
 * and on decline the operation is cancelled.
 *
 * @param force whether the user bypassed the check with `--force`/`-y`
 * @param operation performs the write; receives whether the data catalog check
 *   header should be sent
 * @returns `true` if the operation completed, `false` if the user cancelled
 */
export async function withDataCatalogCheck(
	force: boolean | undefined,
	operation: (dataCatalogCheck: boolean) => Promise<void>
): Promise<boolean> {
	try {
		await operation(!force);
		return true;
	} catch (error) {
		if (force || !isDataCatalogConflict(error)) {
			throw error;
		}
		const confirmed = await confirm(DATA_CATALOG_CONFLICT_PROMPT);
		if (!confirmed) {
			logger.log("Operation cancelled.");
			return false;
		}
		await operation(false);
		return true;
	}
}
